schema = '''accounts(account_id INTEGER PRIMARY KEY, signup_date DATE, region TEXT)
sessions(session_id INTEGER PRIMARY KEY, account_id INTEGER, started_at TIMESTAMPTZ, converted BOOLEAN)
orders(order_id INTEGER PRIMARY KEY, account_id INTEGER, ordered_at TIMESTAMPTZ, amount NUMERIC, status TEXT)
contacts(contact_id INTEGER PRIMARY KEY, account_id INTEGER, contacted_at TIMESTAMPTZ, channel TEXT)
All timestamps are instants. Amount is order revenue. Use America/New_York for local-date questions. Use PostgreSQL. Unless stated otherwise, include only status = 'paid' orders; NULL amounts contribute zero revenue.'''
sql_rows = [
("Write SQL to return each account's total paid revenue. Return account_id and revenue. Include accounts with no paid orders and show their revenue as 0.", "SELECT a.account_id, COALESCE(SUM(o.amount),0) AS revenue FROM accounts a LEFT JOIN orders o ON o.account_id=a.account_id AND o.status='paid' GROUP BY a.account_id;", 'Use a left join from accounts|Keep paid filtering in the join|Aggregate at account grain|Return zero for missing revenue'),
("Write SQL to return the 3 accounts with the highest total paid revenue. Return account_id and revenue, highest revenue first. If revenues tie, put the smaller account_id first. Consider only accounts with paid orders.", "SELECT account_id, COALESCE(SUM(amount),0) AS revenue FROM orders WHERE status='paid' GROUP BY account_id ORDER BY revenue DESC, account_id LIMIT 3;", 'Filter paid orders|Aggregate revenue by account|Use deterministic ordering|Limit after aggregation'),
("Write SQL to calculate session conversion rate for each New York calendar day that has sessions. Return day and rate. A converted value of TRUE counts as a conversion; FALSE or NULL does not. Include all sessions in the denominator and return rate between 0 and 1.", "SELECT (started_at AT TIME ZONE 'America/New_York')::date AS day, AVG(CASE WHEN converted IS TRUE THEN 1.0 ELSE 0.0 END) AS rate FROM sessions GROUP BY 1;", 'Convert to the local timezone|Use all sessions as denominator|Avoid integer division|Handle NULL conversion explicitly'),
("Write SQL to find accounts with at least one session and no paid orders. Return each matching account_id once.", "SELECT a.account_id FROM accounts a WHERE EXISTS (SELECT 1 FROM sessions s WHERE s.account_id=a.account_id) AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.account_id=a.account_id AND o.status='paid');", 'Require at least one session|Use a correct anti-join or NOT EXISTS|Apply paid status inside the order condition|Avoid duplicate accounts'),
("Write SQL to return the latest paid order for each account that has paid orders. Return account_id, order_id, ordered_at, and amount. If two orders have the same timestamp, keep the larger order_id.", "SELECT order_id,account_id,ordered_at,amount FROM (SELECT o.*, ROW_NUMBER() OVER(PARTITION BY account_id ORDER BY ordered_at DESC,order_id DESC) AS rn FROM orders o WHERE status='paid') t WHERE rn=1;", 'Partition by account|Filter paid orders|Specify a deterministic tie-breaker|Select exactly one row per account'),
("Write SQL to find accounts with at least 2 paid orders during August 2026 in New York time. Include orders from August 1 at 00:00 up to, but not including, September 1 at 00:00. Return account_id.", "SELECT account_id FROM orders WHERE status='paid' AND ordered_at >= TIMESTAMPTZ '2026-08-01 00:00 America/New_York' AND ordered_at < TIMESTAMPTZ '2026-09-01 00:00 America/New_York' GROUP BY account_id HAVING COUNT(*)>=2;", 'Use local-month instant boundaries|Use an exclusive upper bound|Filter paid orders|Filter groups with HAVING'),
("Write SQL to return, for each region, the number of accounts and the number of accounts with at least one paid order. Count each account once, even if it has several orders. Include regions with no paid orders.", "SELECT a.region,COUNT(*) AS accounts,COUNT(*) FILTER(WHERE EXISTS(SELECT 1 FROM orders o WHERE o.account_id=a.account_id AND o.status='paid')) AS buyers FROM accounts a GROUP BY a.region;", 'Preserve account grain|Avoid order join fanout|Count buyers once|Group by region'),
("Write SQL to return each paid order and the number of hours since that account's previous paid order. Return account_id, order_id, and gap_hours. Sort orders by timestamp, then by smaller order_id first. The first paid order for an account should have a NULL gap.", "SELECT account_id,order_id,EXTRACT(EPOCH FROM (ordered_at-LAG(ordered_at) OVER(PARTITION BY account_id ORDER BY ordered_at,order_id)))/3600.0 AS gap_hours FROM orders WHERE status='paid';", 'Use LAG within account|Order deterministically|Convert interval to hours|Keep the first gap NULL'),
("Write SQL to return paid revenue for each New York calendar day and the running total up to that day. Return day, revenue, and cumulative, sorted by day. Include only days with paid orders.", "WITH daily AS (SELECT (ordered_at AT TIME ZONE 'America/New_York')::date AS day,COALESCE(SUM(amount),0) AS revenue FROM orders WHERE status='paid' GROUP BY 1) SELECT day,revenue,SUM(revenue) OVER(ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative FROM daily ORDER BY day;", 'Aggregate at local-day grain first|Filter paid orders|Use an explicit running window|Order output by date'),
("Write SQL to find accounts contacted through both email and LinkedIn. Other contact channels are allowed. Return each matching account_id once. The channel values are 'email' and 'linkedin'.", "SELECT account_id FROM contacts GROUP BY account_id HAVING COUNT(*) FILTER(WHERE channel='email')>0 AND COUNT(*) FILTER(WHERE channel='linkedin')>0;", 'Group at account grain|Require both channels|Allow other channels|Avoid requiring exactly two total rows'),
("Write SQL to calculate average paid order amount for each region. Average over orders, not account totals. Count a NULL order amount as 0. Include regions with no paid orders and return 0 for their average.", "SELECT a.region,COALESCE(AVG(COALESCE(o.amount,0)) FILTER(WHERE o.order_id IS NOT NULL),0) AS aov FROM accounts a LEFT JOIN orders o ON o.account_id=a.account_id AND o.status='paid' GROUP BY a.region;", 'Use order-level rather than account-level mean|Preserve regions without orders|Treat NULL amount as zero|Do not count synthetic left-join rows'),
("Write SQL to find paid orders whose amount is strictly greater than the average paid order amount for the same account. Count NULL amounts as 0 in both the average and the comparison. Return order_id, account_id, and the original amount.", "SELECT order_id,account_id,amount FROM (SELECT o.*,AVG(COALESCE(amount,0)) OVER(PARTITION BY account_id) AS mean_amount FROM orders o WHERE status='paid') t WHERE COALESCE(amount,0)>mean_amount;", 'Compute per-account mean|Use paid orders consistently|Apply strict greater-than comparison|Handle NULL amount consistently'),
("Write SQL to rank accounts by total paid revenue within each region. Include only accounts with paid orders. Return account_id, region, revenue, and rank. Equal revenues share the same rank; the next rank should have no gap, such as 1, 1, 2.", "WITH r AS (SELECT a.account_id,a.region,COALESCE(SUM(o.amount),0) AS revenue FROM accounts a JOIN orders o ON o.account_id=a.account_id AND o.status='paid' GROUP BY a.account_id,a.region) SELECT *,DENSE_RANK() OVER(PARTITION BY region ORDER BY revenue DESC) AS rank FROM r;", 'Aggregate before ranking|Partition by region|Use DENSE_RANK|Do not break revenue ties in the rank expression'),
("Write SQL to return all dates from August 1 through August 7, 2026, and the paid revenue on each date in New York time. Return day and revenue, sorted by day. Include dates with no paid orders and show 0 for their revenue.", "WITH dates AS (SELECT d::date AS day FROM generate_series(TIMESTAMP '2026-08-01',TIMESTAMP '2026-08-07',INTERVAL '1 day') d), revenue AS (SELECT (ordered_at AT TIME ZONE 'America/New_York')::date AS day, SUM(amount) AS revenue FROM orders WHERE status='paid' GROUP BY 1) SELECT d.day,COALESCE(r.revenue,0) AS revenue FROM dates d LEFT JOIN revenue r USING(day) ORDER BY d.day;", 'Generate the complete date spine|Aggregate orders before joining|Use New York dates|Fill absent totals with zero'),
("Write SQL to find accounts that placed at least one paid order on their signup date. Convert the order timestamp to a New York calendar date before comparing it with signup_date. Return each matching account_id once.", "SELECT a.account_id FROM accounts a WHERE EXISTS(SELECT 1 FROM orders o WHERE o.account_id=a.account_id AND o.status='paid' AND (o.ordered_at AT TIME ZONE 'America/New_York')::date=a.signup_date);", 'Compare dates in the business timezone|Use paid orders|Return one row per account|Compare with the signup date'),
("Write SQL to return each contact_id and a TRUE/FALSE flag called followed_by_order. The flag is TRUE if that same account placed a paid order within 48 hours after the contact. Include an order at the exact contact time; exclude one at exactly 48 hours. Return one row per contact.", "SELECT c.contact_id,EXISTS(SELECT 1 FROM orders o WHERE o.account_id=c.account_id AND o.status='paid' AND o.ordered_at>=c.contacted_at AND o.ordered_at<c.contacted_at+INTERVAL '48 hours') AS followed_by_order FROM contacts c;", 'Keep one row per contact|Match the account|Use correct half-open time bounds|Avoid confusing association with causal attribution'),
("Write SQL to calculate each account's share of all paid revenue as a percentage from 0 to 100. Return account_id and percent for accounts with paid orders. If total paid revenue is 0, return NULL for percent.", "WITH r AS (SELECT account_id,COALESCE(SUM(amount),0) AS revenue FROM orders WHERE status='paid' GROUP BY account_id) SELECT account_id,100.0*revenue/NULLIF(SUM(revenue) OVER(),0) AS percent FROM r;", 'Aggregate account revenue|Compute global revenue with a window|Avoid integer division|Guard division by zero'),
("Write SQL to find accounts that had sessions on at least 3 consecutive New York calendar days. Several sessions on one day count as one day. Return each matching account_id once.", "WITH dates AS (SELECT DISTINCT account_id,(started_at AT TIME ZONE 'America/New_York')::date AS day FROM sessions), islands AS (SELECT account_id,day-(ROW_NUMBER() OVER(PARTITION BY account_id ORDER BY day))::integer AS island FROM dates) SELECT DISTINCT account_id FROM islands GROUP BY account_id,island HAVING COUNT(*)>=3;", 'Deduplicate account-date pairs|Use a gaps-and-islands approach|Respect local dates|Return accounts with a run of at least three'),
("Write SQL to return 3 totals for each region: number of accounts, number of sessions, and paid revenue. Include accounts with no activity. Avoid counting a session or order multiple times when an account has several of each.", "WITH s AS (SELECT account_id,COUNT(*) AS n FROM sessions GROUP BY account_id),o AS (SELECT account_id,COALESCE(SUM(amount),0) AS revenue FROM orders WHERE status='paid' GROUP BY account_id) SELECT a.region,COUNT(*) AS accounts,COALESCE(SUM(s.n),0) AS sessions,COALESCE(SUM(o.revenue),0) AS revenue FROM accounts a LEFT JOIN s USING(account_id) LEFT JOIN o USING(account_id) GROUP BY a.region;", 'Preaggregate both fact tables|Join at account grain|Keep accounts without activity|Coalesce missing totals'),
("Write SQL to return each account's second paid order. Sort orders from earliest to latest; if timestamps tie, put the smaller order_id first. Return account_id, order_id, and ordered_at. Leave out accounts with fewer than 2 paid orders.", "SELECT account_id,order_id,ordered_at FROM (SELECT account_id,order_id,ordered_at,ROW_NUMBER() OVER(PARTITION BY account_id ORDER BY ordered_at,order_id) AS rn FROM orders WHERE status='paid') t WHERE rn=2;", 'Use ROW_NUMBER by account|Filter paid orders before ranking|Specify ascending deterministic ordering|Exclude accounts with fewer than two orders'),
]
for i,(prompt,query,points) in enumerate(sql_rows,1):
    questions.append(dict(id=f'sql-{i:02}',category='SQL',difficulty='Hard' if i>=14 else 'Medium',prompt=prompt,rubric=points.split('|'),schema=schema,expectedQuery=query))
(ROOT/'data/questions.json').write_text(json.dumps(questions,ensure_ascii=False,indent=2)+'\n')
(ROOT/'data/bq.json').write_text(json.dumps([q for q in questions if q['category']=='BQ'],ensure_ascii=False,indent=2)+'\n')
rows = ',\n'.join("('%s', '%s', '%s'::jsonb)"%(q['id'],q['category'],json.dumps(q,ensure_ascii=False).replace("'","''")) for q in questions)
(ROOT/'supabase/seed.sql').write_text('-- Original questions authored for Offer Quest. Safe to run repeatedly.\nINSERT INTO public.question_bank (id, category, content) VALUES\n'+rows+'\nON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, content=EXCLUDED.content;\n')
print({c:sum(q['category']==c for q in questions) for c in ['ML','AI/LLM','SQL','Python','BQ']})
